# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_salv_a import S,F
W=[
E('saving','/ˈseɪvɪŋ/','节省；节省下来的量；节约的','本来要花十元，现在只花八元，少花的两元就是 a saving。','save + -ing；动词名词化后可说节省行为，也可指省下来的量。',S+[['save + -ing → saving','保全、节约的行为 → 省下来的数量']],'a saving of two hours 是省下两小时；make a saving 是节约开支。saving 也能是 save 的现在分词，如 I’m saving for a bike。“省下一笔”和“正在攒钱”要靠句子区分。','a saving of ten dollars；a substantial saving；cost saving；be saving for something。','saving 单数常指一次节约量；savings 常指积蓄，也可指多项节省。不要把所有 -ing 都当成正在进行。',('Buying the tickets together gave us a saving of twenty dollars.','一起买票让我们省了二十美元。'),('She is saving for a new bicycle.','她正在攒钱买一辆新自行车。'),sources=['https://www.etymonline.com/word/saving','https://en.wiktionary.org/wiki/saving']),
E('savings','/ˈseɪvɪŋz/','积蓄；存款；节省下来的钱','一次次没有花掉的钱留下来，慢慢成为手头的一笔积蓄。','saving 的复数形式；在积蓄义上通常整体使用复数。',S+[['saving → savings','省下来的量 → 累积保存的钱；多项节省']],'my savings 是我的积蓄，不只是一张具体存款凭证。cost savings 则常说减少的成本，未必是在账户里另存了一笔钱。a savings account 中 savings 修饰 account。','personal savings；life savings；a savings account；cost savings。','积蓄义通常说 My savings are...，不能因为中文是一笔钱就自动用 is；saving 可单独指一项节约。',('They used part of their savings to repair the roof.','他们用了一部分积蓄修屋顶。'),('The new process produced significant cost savings.','新流程大幅节省了成本。'),sources=['https://en.wiktionary.org/wiki/savings','https://dictionary.cambridge.org/dictionary/english/savings']),
E('saver','英 /ˈseɪvə/；美 /ˈseɪvər/','储蓄者；节省某物的人或工具','把 save 的动作放到执行者身上：有人爱攒钱，也有工具帮你省时间。','save + -er；早期也有救助者义，现代常指储蓄者或节约工具。',S+[['save + -er → saver','做保存、节省动作的人或物']],'a regular saver 是经常储蓄的人；a time saver 是省时间的办法或工具。这个 -er 不限定必须是人，和 opener 可以是开瓶器一样。','a regular saver；a careful saver；a time saver；a space saver。','saver 多谈储蓄或节约，savior/saviour 强调拯救者；它们不能只因为都和 save 有关就随便替换。',('She has always been a careful saver.','她一直很注意攒钱。'),('This keyboard shortcut is a real time saver.','这个快捷键真能省时间。'),sources=['https://www.etymonline.com/word/saver','https://en.wiktionary.org/wiki/saver']),
E('safekeeping','/ˌseɪfˈkiːpɪŋ/','妥善保管；安全保存','把重要物品交给可靠的人或放进可靠的地方，确保不丢、不坏。','safe + keeping 的英语复合；中古英语已有 safe kepyng。',F+[['safe 安全的 + keeping 保管 → safekeeping','安全保管这种行为或状态']],'for safekeeping 是为了妥善保管；give someone something for safekeeping 是请某人代为保管。它关心保管期间不出问题，不只是把东西随手放在哪里。','for safekeeping；in someone’s safekeeping；leave something for safekeeping。','storage 强调存放，safekeeping 多强调有人负责、物品受到保护。也可分写 safe keeping。',('He left the original letter with his sister for safekeeping.','他把信件原件交给姐姐妥善保管。'),('The keys were placed in a locked drawer for safekeeping.','钥匙被放进上锁的抽屉妥善保管。'),sources=['https://www.dictionary.com/browse/safekeeping','https://www.oxfordlearnersdictionaries.com/definition/english/safe-keeping']),
E('lifesaver','英 /ˈlaɪfˌseɪvə/；美 /ˈlaɪfˌseɪvər/','救命的人或物；解燃眉之急的帮手','真的把人从危险中救回来，或夸张地说“你这回可救了我”。','life 生命 + saver 救助者、保全者；两个成分合成。',S+[['life 生命 + saver 救助者 → lifesaver','救命者；后来也指帮了大忙的人或物']],'You’re a lifesaver! 日常常是热情道谢：你帮我解决了急事，不表示刚才一定有人濒临死亡。谈水上活动时也可指救生人员或救生物件，具体看上下文。','be a lifesaver；a real lifesaver；call someone a lifesaver。','lifeguard 通常是负责水域安全的救生员岗位；lifesaver 范围更广，也常是夸张的感谢。',('Thanks for bringing a spare charger—you’re a lifesaver!','谢谢你带了备用充电器，你可帮了大忙！'),('The rescue team described the flotation device as a lifesaver.','救援队称那个浮力装置救了命。'),sources=['https://en.wiktionary.org/wiki/lifesaver','https://www.etymonline.com/word/lifesaver']),
E('lifesaving','/ˈlaɪfˌseɪvɪŋ/','救命的；救生；救生活动','目标很具体：使人的生命不至于在事故或疾病中失去。','life 生命 + saving 救助；不是先有英语 life 再演变成 save。',S+[['life 生命 + saving 救助 → lifesaving','挽救生命的；救生活动']],'lifesaving equipment 是救生设备；lifesaving skills 是救生技能。它也可作名词指救生活动，尤其见于水上救援和相关运动。','lifesaving equipment；lifesaving skills；lifesaving treatment。','helpful 只说有帮助，lifesaving 把作用提高到保住生命。普通生活用品被夸 lifesaver 时，语气可以比 lifesaving treatment 轻松得多。',('The volunteers received training in lifesaving skills.','志愿者接受了救生技能培训。'),('The boat carried essential lifesaving equipment.','船上配备了必需的救生设备。'),sources=['https://en.wiktionary.org/wiki/lifesaving','https://www.merriam-webster.com/dictionary/lifesaving'])]
